// Simulated ESP32 OBD-II batch - same JSON format the real device POSTs.
// A drive cycle: idle -> accelerate -> cruise -> brake, engine warming up over ~20 minutes.
const BATCH = 5, STEP = 2;               // 5 records, 2 s apart (like "Save a sample every 2 s")
const now = Math.floor(Date.now() / 1000);
const sd = $getWorkflowStaticData('global');
if (!sd.start) sd.start = now;            // remembers when the "engine" started
if (!sd.fuel) sd.fuel = 64;
const records = [];
for (let i = BATCH - 1; i >= 0; i--) {
  const t = now - i * STEP, run = t - sd.start;
  const phase = (run % 120) / 120;        // 2-minute drive cycle
  let speed = phase < 0.1 ? 0 : phase < 0.35 ? (phase - 0.1) / 0.25 * 90 : phase < 0.8 ? 90 + 8 * Math.sin(run / 7) : Math.max(0, 90 - (phase - 0.8) / 0.2 * 90);
  speed = Math.round(speed);
  const rpm = speed === 0 ? 780 + Math.round(Math.random() * 40) : Math.round(1100 + speed * 22 + Math.random() * 120);
  const throttle = speed === 0 ? 15.7 : +(16 + (phase < 0.35 ? 30 : 12) + Math.random() * 6).toFixed(1);
  const coolant = Math.min(91, Math.round(40 + run / 15));          // warms up to 91 C
  sd.fuel = Math.max(5, sd.fuel - 0.002);
  records.push({ ts: t, boot: 7, uptime: 500 + run, mode: 'live', values: {
    rpm, speed, coolant, throttle,
    load: +(speed === 0 ? 21 : 30 + Math.random() * 25).toFixed(1),
    intake: 31 + Math.round(run / 300),
    voltage: +(14.0 + Math.random() * 0.2).toFixed(2),
    fuel: +sd.fuel.toFixed(1),
    oil: Math.min(98, Math.round(38 + run / 13)),
  }});
}
return [{ json: { device: 'OBD-Monitor', type: 'log', records } }];
